        var sm = tfRun({
            github: {
                prList: JSON.stringify([
                    tfPr(302, ['agent:review'], 'moved/branch')
                ]),
                prComments: [{
                    body: '\u26A0\uFE0F trigger-failed other/branch \u2014 attempt 2/3 a…

