        return sm;
    }

    function triggeredRefs(sm) {
        return sm.capturedTriggers.map(function (t) { return t.ref; });
    }

    function parkAdds(sm) {
        return sm.capturedPrLabelAdds.filter(function (a) {
            return (a.labels || []).indexOf('validation_failed') !== -1;
