        var sm2 = makeSmAgent(Object.assign(tfConfig('o', 'r'), {
            captureConsole: true,
            github: { items: function () { return [deadPr]; }, prComments: prior },
            onTrigger: function () { throw new Error(NO_REF_ERR); }
