    }

    var DEAD_REF = 'gone/deleted-branch';
    var NO_REF_ERR = '422: No ref found for: ' + DEAD_REF;

    function tfRun(opts) {
        var gh = Object.assign({ realSource: true }, opts.github || {});
        var sm = makeSmAgent(Object.assign(tfConfig('o', 'r'), {
