    if (opts.runAsync) smMocks.runAsync = opts.runAsync;
    if (opts.extraMocks) { for (var em in opts.extraMocks) { if (opts.extraMocks.hasOwnProperty(em)) smMocks[em] = opts.extraMocks[em]; } }

