    test('the failure is recorded with a reason: a trigger-failed marker comment (attempt 1/3), no park on the first failure', function () {
        var sm = tfRun({
            github: { prList: JSON.stringify([
                tfPr(302, ['agent:review', 'priority_blocker'], DEAD_REF)
