    // neither: they act directly, no dispatch happens.
    if ((needsJql ? !rule.jql : !rule.query) || (!rule.configFile && !rule.inputs && !rule.localAction)) {
        console.warn('  ⚠️  Skipping rule — ' + (needsJql ? 'jql' : 'query') +
