                  query: { type: 'pr', labels: ['agent:rework'], draft: false },
                  inputs: { pr: '{prNumber}', leg: 'rework' },
                  workflowRef: '{branch}', limit: 1 }
            ];
        }

        // Tick 1: both lanes fail the same dead head — ONE marker.
        var sm1 = makeSmAgent(Object.assign(tfConfig('o', 'r'), {
            captureConsole: true,
