        var prior = [1, 2].map(function (n) {
            return { body: '\u26A0\uFE0F trigger-failed ' + DEAD_REF + ' \u2014 attempt ' + n +
                '/3 at 2026-10-16T13:0' + n + ':00Z — prior failure' };
