function localIssueExists(repoInfo, issueNumber) {
    if (typeof github_get_issue !== 'function') return true;
    var res;
    try {
        res = github_get_issue({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            issueNumber: issueNumber
