                ' no-ref failures on ' + item.branch + ') — validation_failed park, slot stays open');
        } else {
            tr.postComment(item.prNumber,
                triggerFailuresModule.triggerFailMarkerLine(count, item.branch, cap, new Date().toISOString()) +
